impl Solution {
    pub fn add_negabinary(arr1: Vec<i32>, arr2: Vec<i32>) -> Vec<i32> {
        let mut result = Vec::new();
        let mut carry = 0;
        let mut i = arr1.len() as i32 - 1;
        let mut j = arr2.len() as i32 - 1;

        while i >= 0 || j >= 0 || carry != 0 {
            let digit1 = if i >= 0 { arr1[i as usize] } else { 0 };
            let digit2 = if j >= 0 { arr2[j as usize] } else { 0 };

            let total = digit1 + digit2 + carry;
            let negabinary_digit = total % 2;
            carry = (total - negabinary_digit) / (-2);

            result.push(negabinary_digit);
            i -= 1;
            j -= 1;
        }

        // Remove leading zeros
        while result.len() > 1 && result.last() == Some(&0) {
            result.pop();
        }

        result.reverse();
        result
    }
}

